age.example:
filter {
  age {
    target => "[event][age_seconds]"
  }
  if [event][age_seconds] > 86400 {
    mutate { add_tag => ["stale_event"] }
  }
}

aggregate.example:
filter {
  aggregate {
    task_id => "%{transaction_id}"
    code => "map['event_count'] ||= 0; map['event_count'] += 1"
    push_map_as_event_on_timeout => true
    timeout => 120
    inactivity_timeout => 30
    timeout_tags => ["aggregated_transaction"]
  }
}

cipher.example:
filter {
  cipher {
    algorithm        => "aes-256-cbc"
    mode             => "encrypt"
    source           => "[user][email]"
    target           => "[user][email_encrypted]"
    key              => "${LOGSTASH_CIPHER_KEY}"
    key_size         => 32
    iv_random_length => 16
    base64           => true
  }
}

clone.example:
filter {
  clone {
    clones => [ "for_archive", "for_analytics" ]
  }

  if "for_archive" in [tags] {
    mutate { add_field => { "[stream]" => "cold_storage" } }
  }
  if "for_analytics" in [tags] {
    mutate { add_field => { "[stream]" => "live_dashboards" } }
  }
}

csv.example:
filter {
  csv {
    source    => "message"
    columns   => [ "timestamp", "method", "path", "status", "duration_ms" ]
    separator => ","
    convert   => {
      "status"      => "integer"
      "duration_ms" => "float"
    }
    skip_empty_columns => true
  }
}

date.example:
filter {
  date {
    match    => [ "[event][start]", "ISO8601", "yyyy-MM-dd HH:mm:ss" ]
    target   => "@timestamp"
    timezone => "UTC"
    tag_on_failure => [ "_dateparsefailure" ]
  }
}

de_dot.example:
filter {
  de_dot {
    fields    => [ "process.name", "container.image.name" ]
    separator => "_"
    recursive => false
  }
}

# Alternative: turn dotted names into nested sub-fields.
# filter {
#   de_dot {
#     fields => [ "process.name" ]
#     nested => true
#   }
# }

drop.example:
filter {
  if [http][request][path] == "/healthz" {
    drop { }
  }

  if [log][level] == "DEBUG" {
    drop { percentage => 90 }
  }
}

elapsed.example:
filter {
  if [log][type] == "request_start" {
    mutate { add_tag => [ "start_event" ] }
  }
  if [log][type] == "request_end" {
    mutate { add_tag => [ "end_event" ] }
  }

  elapsed {
    start_tag       => "start_event"
    end_tag         => "end_event"
    unique_id_field => "[transaction][id]"
    timeout         => 60
    new_event_on_match => false
  }
}

fingerprint.example:
filter {
  fingerprint {
    source               => [ "[user][id]", "[event][action]", "@timestamp" ]
    method               => "SHA256"
    concatenate_sources  => true
    target               => "[event][id]"
    base64encode         => true
  }
}

geoip.example:
filter {
  geoip {
    source => "[client][ip]"
    target => "[client][geo]"
    fields => [ "country_name", "city_name", "location", "continent_code" ]
    tag_on_failure => [ "_geoip_lookup_failure" ]
  }
}

grok.example:
filter {
  grok {
    match => {
      "message" => "%{TIMESTAMP_ISO8601:ts} \[%{LOGLEVEL:level}\] %{DATA:logger} - %{GREEDYDATA:msg}"
    }
    overwrite       => [ "message" ]
    tag_on_failure  => [ "_grokparsefailure" ]
    timeout_millis  => 2000
  }
}

json.example:
filter {
  json {
    source => "message"
    target => "payload"
    skip_on_invalid_json => false
    tag_on_failure => [ "_jsonparsefailure" ]
  }
}

kv.example:
filter {
  kv {
    source         => "message"
    target         => "params"
    field_split    => "&?"
    value_split    => "="
    include_keys   => [ "user_id", "session", "action" ]
    transform_key  => "lowercase"
    trim_value     => "\"'"
    tag_on_failure => [ "_kvparsefailure" ]
  }
}

metricize.example:
filter {
  metricize {
    metrics             => [ "cpu_pct", "mem_pct", "disk_pct" ]
    metric_field_name   => "metric"
    value_field_name    => "value"
    drop_original_event => true
  }
}

metrics.example:
filter {
  metrics {
    meter          => [ "events.ingested", "events.parse_failures" ]
    timer          => { "http.response.time_ms" => "[http][response][time_ms]" }
    rates          => [ 1, 5 ]
    percentiles    => [ 50, 95, 99 ]
    flush_interval => 60
    add_tag        => [ "pipeline_metrics" ]
  }
}

mutate.example:
filter {
  mutate {
    rename => {
      "[host]" => "[host][name]"
      "[src]"  => "[source][ip]"
    }
    convert => {
      "[http][response][status_code]" => "integer"
      "[http][response][time_ms]"     => "float"
    }
    gsub => [
      "[url][path]", "/\\d+", "/:id"
    ]
    lowercase => [ "[log][level]" ]
    remove_field => [ "raw_message", "tmp" ]
    tag_on_failure => [ "_mutateparsefailure" ]
  }
}

prune.example:
filter {
  prune {
    whitelist_names => [ "^@?timestamp$", "^host(\\..+)?$", "^log(\\..+)?$", "^message$", "^service(\\..+)?$" ]
    blacklist_names => [ "^_+$" ]
    interpolate     => false
  }
}

ruby.example:
filter {
  ruby {
    code => '
      status = event.get("[http][response][status_code]").to_i
      event.set("[http][response][status_family]", "#{status / 100}xx")
    '
    tag_on_exception           => "_rubyexception"
    tag_with_exception_message => true
  }
}

sleep.example:
filter {
  if "load_test" in [tags] {
    sleep {
      time  => 0.1
      every => 10
    }
  }
}

syslog_pri.example:
filter {
  grok {
    match => { "message" => "<%{NONNEGINT:syslog_pri}>%{GREEDYDATA:syslog_message}" }
  }
  syslog_pri {
    syslog_pri_field_name => "syslog_pri"
    use_labels => true
  }
}

throttle.example:
filter {
  throttle {
    key         => "%{[log][level]}|%{[service][name]}"
    period      => 60
    after_count => 50
    add_tag     => [ "throttled" ]
  }

  if "throttled" in [tags] {
    drop { }
  }
}

translate.example:
filter {
  translate {
    source      => "[http][response][status_code]"
    target      => "[http][response][status_family]"
    dictionary  => {
      "200" => "success"
      "201" => "success"
      "301" => "redirect"
      "400" => "client_error"
      "401" => "unauthorized"
      "404" => "not_found"
      "500" => "server_error"
    }
    fallback    => "other"
    exact       => true
    override    => true
  }
}

xml.example:
filter {
  xml {
    source        => "message"
    target        => "[payload][xml]"
    store_xml     => true
    force_array   => false
    suppress_empty => true
    xpath         => {
      "//order/id/text()"       => "[order][id]"
      "//order/customer/text()" => "[order][customer]"
    }
  }
}
